mapper.select:
SELECT
	COUNT(*) AS TOTAL_CNT,
	SUM(CASE WHEN A.STATUS_CD = '1' THEN 1 ELSE 0 END) AS PROC_CNT,
	SUM(CASE WHEN A.STATUS_CD = '2' THEN 1 ELSE 0 END) AS HOLD_CNT,
	SUM(CASE WHEN A.STATUS_CD = '3' THEN 1 ELSE 0 END) AS REJECT_CNT,
	SUM(CASE WHEN A.STATUS_CD = '4' THEN 1 ELSE 0 END) AS PENDING_CNT
FROM dbo.TMN_MINWON A
WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.DONG_ID = #{DONG_ID}
	AND A.GBN = #{GBN} AND A.LINE_GBN = #{LINE_GBN}


		AND A.DONG_ID = #{DONG_ID}
		AND A.LINE_GBN = #{LINE_GBN}
		AND A.HO_ID  = #{HO_ID}


		AND A.DONG_ID = #{DONG_ID}
		AND A.LINE_GBN = #{LINE_GBN}

			AND A.HO_ID  = #{HO_ID} AND A.LINE_NO = #{LINE_NO}



		AND A.MINWON_AREAR_SEQ  = #{MINWON_AREAR_SEQ}

SELECT A.SLIP_NO AS SLIP_NO, A.MINWON_DATE AS MINWON_DATE, A.MINOWN_GBN AS MINOWN_GBN, A.MINOWN_GBN + CHAR(13) + CHAR(10) + A.DESCR AS DESCR A.STATUS_CD AS STATUS_CD, CASE WHEN A.STATUS_CD = '1' THEN '처리' WHEN A.STATUS_CD = '2' THEN '보류' WHEN A.STATUS_CD = '3' THEN '반려' WHEN A.STATUS_CD = '4' THEN '처리중' ELSE '미결' END AS STATUS_NAME, B.WORK_USER AS WORK_USER FROM dbo.TMN_MINWON A LEFT JOIN ( SELECT W1.OFFICE_CODE, W1.SLIP_NO, W1.MINWON_DATE, W1.WORK_USER FROM dbo.TMN_MINWON_WORK W1 JOIN ( SELECT OFFICE_CODE, SLIP_NO, MINWON_DATE, MAX(WORK_SEQ) AS MAX_WORK_SEQ FROM dbo.TMN_MINWON_WORK GROUP BY OFFICE_CODE, SLIP_NO, MINWON_DATE ) W2 ON W1.OFFICE_CODE = W2.OFFICE_CODE AND W1.SLIP_NO = W2.SLIP_NO AND W1.MINWON_DATE = W2.MINWON_DATE AND W1.WORK_SEQ = W2.MAX_WORK_SEQ ) B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.SLIP_NO = B.SLIP_NO AND A.MINWON_DATE = B.MINWON_DATE WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND A.GBN = #{GBN}
AND A.DONG_ID = #{DONG_ID} AND A.LINE_GBN = #{LINE_GBN} AND A.HO_ID = #{HO_ID}
AND A.DONG_ID = #{DONG_ID} AND A.LINE_GBN = #{LINE_GBN}
AND A.HO_ID = #{HO_ID} AND A.LINE_NO = #{LINE_NO}
AND A.MINWON_AREAR_SEQ = #{MINWON_AREAR_SEQ}
ORDER BY CONVERT(INT, A.MINWON_DATE) DESC, CONVERT(INT, A.SLIP_NO) DESC
